import { createLearningEngine } from './learning-engine.js';
import { MEL_LEARNING_BENCHMARK_CASES, runLearningBenchmark, scoreBenchmarkResponse } from './benchmark-suite.js';
import { extractModelText } from '../models/ModelRouter.js';
import { standardRegistry } from '../models/ModelRegistry.js';
import { CANONICAL_LEARNING_BENCHMARK_SUITE, benchmarkSuiteFingerprint } from '../evaluation/benchmarks.js';
import { assertAdapterApprovalForArtifact, assertAdapterArtifactForPlan } from './lora-plan.js';
import { compareLoraImpact, runLoraImpactBenchmark } from './lora-impact-benchmark.js';

export const DEFAULT_OPERATOR_BENCHMARK_MODEL = '@cf/zai-org/glm-4.7-flash';

function cleanModelId(value, fallback) {
  const model = String(value || '').trim();
  return model || fallback;
}

function cleanQuality(value, fallback = 0.65) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(0, Math.min(1, number));
}

// A diagnostic benchmark may intentionally use fewer concurrent requests to
// distinguish provider saturation from a genuinely poor adapter. The two
// baseline/candidate streams still run in parallel, so effective peak is 2x.
export function resolveOperatorLoraBenchmarkConcurrency(value) {
  if (value === undefined || value === null || value === '') return 4;
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1 || n > 4) {
    const error = new Error('LORA_BENCHMARK_CONCURRENCY_INVALID');
    error.code = 'LORA_BENCHMARK_CONCURRENCY_INVALID';
    throw error;
  }
  return n;
}

// Default benchmarking remains parallel. Explicit diagnostic mode runs the
// same baseline/candidate workload serially, including the impact pair.
// This changes only scheduling: not prompts, scoring, LoRA activation or retries.
export async function runLoraBenchmarkPair(tasks, serial = false) {
  if (!Array.isArray(tasks) || tasks.length !== 2 || tasks.some(task => typeof task !== 'function')) {
    const error = new Error('LORA_BENCHMARK_PAIR_INVALID');
    error.code = 'LORA_BENCHMARK_PAIR_INVALID';
    throw error;
  }
  if (serial === true) return [await tasks[0](), await tasks[1]()];
  return Promise.all(tasks.map(task => task()));
}

function benchmarkModel(env = {}) {
  const modelId = cleanModelId(env.MEL_BENCHMARK_MODEL, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  const model = standardRegistry.get(modelId);
  if (!model || model.enabled === false || model.cost === null || model.cost === undefined || Number(model.cost) !== 0) {
    const error = new Error('benchmark_model_not_verified_zero_cost');
    error.code = 'BENCHMARK_MODEL_NOT_VERIFIED_ZERO_COST';
    error.model_id = modelId;
    throw error;
  }
  return modelId;
}

function benchmarkSourceSha(env = {}, options = {}) {
  const compiled = typeof MEL_DEPLOYED_GIT_SHA !== 'undefined' ? String(MEL_DEPLOYED_GIT_SHA || '') : '';
  return String(
    options.source_sha
      || compiled
      || env.MEL_DEPLOYED_GIT_SHA
      || env.MEL_SOURCE_SHA
      || env.CF_PAGES_COMMIT_SHA
      || 'unknown'
  ).trim() || 'unknown';
}

// Workers AI may deliver a JSON-only completion as a structured object
// instead of a string. It is still evidence, but only if it has fields and
// serializes safely. Never turn null, arrays or empty objects into an answer.
export function extractOperatorBenchmarkText(result, extractText = extractModelText) {
  const value = extractText(result);
  if (typeof value === 'string' && value.trim()) return value.trim();
  // Structured benchmark evidence is deliberately separate from chat text.
  // The shared model extractor rejects objects; this benchmark adapter alone
  // may serialize a non-empty JSON response for the scoring engine.
  const structured = value && typeof value === 'object' ? value : result?.response;
  if (structured && typeof structured === 'object' && !Array.isArray(structured) && Object.keys(structured).length) {
    try {
      const text = JSON.stringify(structured);
      if (text && text.length <= 16384) return text;
    } catch {
      // Circular or otherwise unserializable responses are not proof.
    }
  }
  const error = new Error('empty_benchmark_response');
  // Classify the envelope without logging prompt, completion, tokens or provider data.
  const shape = result === null || result === undefined ? 'absent'
    : typeof result === 'string' ? 'blank-string'
    : Array.isArray(result) ? 'array'
    : typeof result !== 'object' ? 'scalar'
    : Object.prototype.hasOwnProperty.call(result, 'response') ? 'response-empty-or-invalid'
    : Object.prototype.hasOwnProperty.call(result, 'choices') ? 'choices-empty-or-invalid'
    : Object.prototype.hasOwnProperty.call(result, 'text') ? 'text-empty-or-invalid'
    : 'unknown-object';
  error.benchmark_response_shape = shape;
  error.code = 'EMPTY_BENCHMARK_RESPONSE';
  throw error;
}

function benchmarkResponder(ai, modelId, extractText, { lora = null, timeout_ms = 45000 } = {}) {
  return async (prompt) => {
    const input = {
      messages: [
        {
          role: 'system',
          content: 'Tu es MEL en mode benchmark. Réponds directement à la consigne, sans commentaire sur le benchmark.',
        },
        { role: 'user', content: String(prompt || '') },
      ],
      temperature: 0,
      // glm-4.7-flash reasons before answering: 512 tokens were spent on
      // reasoning and every benchmark failed EMPTY_BENCHMARK_RESPONSE (25/10).
      max_tokens: 2048,
    };
    if (lora) input.lora = String(lora);
    let timer = null;
    const timeoutMs = Math.max(5000, Math.min(120000, Math.trunc(Number(timeout_ms) || 45000)));
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => {
        const error = new Error('benchmark_inference_timeout');
        error.code = 'BENCHMARK_INFERENCE_TIMEOUT';
        reject(error);
      }, timeoutMs);
    });
    let result;
    try {
      result = await Promise.race([ai.run(modelId, input), timeout]);
    } finally {
      if (timer) clearTimeout(timer);
    }
    return extractOperatorBenchmarkText(result, extractText);
  };
}

export function createZeroCostBenchmarkEvaluator(env = {}, deps = {}) {
  const ai = deps.ai || env.AI;
  if (!ai || typeof ai.run !== 'function') {
    const error = new Error('ai_binding_unavailable');
    error.code = 'AI_BINDING_UNAVAILABLE';
    throw error;
  }

  const modelId = benchmarkModel(env);
  const extractText = deps.extractModelText || extractModelText;
  const respond = benchmarkResponder(ai, modelId, extractText);
  const casesById = new Map(MEL_LEARNING_BENCHMARK_CASES.map((row) => [String(row.id), row]));

  return {
    model_id: modelId,
    evaluator: async (testCase = {}) => {
      const fixture = casesById.get(String(testCase.id || ''));
      if (!fixture) {
        const error = new Error('benchmark_case_fixture_missing');
        error.code = 'BENCHMARK_CASE_FIXTURE_MISSING';
        error.case_id = String(testCase.id || '');
        throw error;
      }
      const response = await respond(fixture.prompt);
      const scored = scoreBenchmarkResponse(response, fixture.rubric);
      return {
        score: scored.score,
        repeated_error: String(testCase.domain || '') === 'taught_error_correction' && scored.score < 1,
        evidence: {
          model_id: modelId,
          case_id: fixture.id,
          checks: scored.checks,
        },
      };
    },
  };
}

export async function ensureZeroCostBenchmarkBaseline(env = {}, options = {}, deps = {}) {
  const createEngine = deps.createLearningEngine || createLearningEngine;
  const engine = createEngine(env);
  const suiteDigest = benchmarkSuiteFingerprint(CANONICAL_LEARNING_BENCHMARK_SUITE);
  const existing = typeof engine.benchmarks === 'function'
    ? await engine.benchmarks({ limit: 200 })
    : [];
  const baseline = (Array.isArray(existing) ? existing : []).find(
    (row) => row?.kind === 'baseline' && row?.metadata?.suite_digest === suiteDigest,
  );

  if (baseline) {
    return {
      status: 'EXISTS',
      created: false,
      score: Number.isFinite(Number(baseline.overall)) ? Number(baseline.overall) : null,
      cases: Number.isFinite(Number(baseline.cases)) ? Number(baseline.cases) : null,
      suite_digest: suiteDigest,
      model_id: baseline.model_id || null,
      source_sha: baseline.source_sha || null,
    };
  }

  const prepared = createZeroCostBenchmarkEvaluator(env, deps);
  const sourceSha = benchmarkSourceSha(env, options);
  const run = await engine.runCanonicalBenchmark({
    kind: 'baseline',
    evaluator: prepared.evaluator,
    model_id: prepared.model_id,
    source_sha: sourceSha,
    metadata: {
      trigger: String(options.trigger || 'scheduled-bootstrap'),
    },
  });

  return {
    status: run?.reused === true ? 'REUSED' : 'RAN',
    created: run?.reused !== true,
    score: Number.isFinite(Number(run?.score?.overall)) ? Number(run.score.overall) : null,
    cases: Number.isFinite(Number(run?.score?.cases)) ? Number(run.score.cases) : null,
    suite_digest: run?.suite_digest || suiteDigest,
    model_id: prepared.model_id,
    source_sha: sourceSha,
  };
}

export async function runOperatorBenchmark(env = {}, options = {}, deps = {}) {
  const ai = deps.ai || env.AI;
  if (!ai || typeof ai.run !== 'function') {
    const error = new Error('ai_binding_unavailable');
    error.code = 'AI_BINDING_UNAVAILABLE';
    throw error;
  }

  const createEngine = deps.createLearningEngine || createLearningEngine;
  const benchmarkRunner = deps.runLearningBenchmark || runLearningBenchmark;
  const extractText = deps.extractModelText || extractModelText;
  // The operator endpoint never accepts a request-selected model. Model choice
  // stays on the trusted server side and must be explicitly zero-cost in the
  // canonical registry before any Workers AI call is allowed.
  const modelId = benchmarkModel(env);
  const sourceSha = benchmarkSourceSha(env, options);

  const respond = benchmarkResponder(ai, modelId, extractText);
  const benchmark = await benchmarkRunner({
    modelId,
    sourceSha,
    metadata: {
      model_id: modelId,
      source_sha: sourceSha,
      trigger: 'professor',
    },
    respond,
  });

  const engine = createEngine(env);
  const persisted = await engine.recordBenchmark({
    cases: benchmark.cases,
    kind: 'operator',
    model_id: modelId,
    source_sha: sourceSha,
    metadata: {
      benchmark_id: benchmark.benchmark_id,
      version: benchmark.version,
      case_count: benchmark.case_count,
      measured_score: benchmark.score,
      trigger: 'professor',
    },
  });

  return {
    benchmark,
    persisted,
    model_id: modelId,
    source_sha: sourceSha,
  };
}

export async function runOperatorLoraBenchmark(env = {}, options = {}, deps = {}) {
  const ai = deps.ai || env.AI;
  if (!ai || typeof ai.run !== 'function') {
    const error = new Error('ai_binding_unavailable');
    error.code = 'AI_BINDING_UNAVAILABLE';
    throw error;
  }

  const plan = options.plan;
  const checkedArtifact = assertAdapterArtifactForPlan({ plan, artifact: options.artifact });
  const checkedApproval = assertAdapterApprovalForArtifact({ plan, artifact: checkedArtifact, approval: options.approval });
  const createEngine = deps.createLearningEngine || createLearningEngine;
  const benchmarkRunner = deps.runLearningBenchmark || runLearningBenchmark;
  const impactRunner = deps.runLoraImpactBenchmark || runLoraImpactBenchmark;
  const extractText = deps.extractModelText || extractModelText;
  const sourceSha = benchmarkSourceSha(env, options);
  const suiteDigest = benchmarkSuiteFingerprint(CANONICAL_LEARNING_BENCHMARK_SUITE);
  const runtimeModel = checkedArtifact.runtime_model;
  const benchmarkConcurrency = resolveOperatorLoraBenchmarkConcurrency(options.benchmark_concurrency);
  const benchmarkSerial = options.benchmark_serial === true;

  const [baseline, candidate] = await runLoraBenchmarkPair([
    () => benchmarkRunner({
      metadata: {
        model_id: runtimeModel,
        source_sha: sourceSha,
        trigger: 'lora-gate-baseline',
        suite_digest: suiteDigest,
      },
      respond: benchmarkResponder(ai, runtimeModel, extractText),
      concurrency: benchmarkConcurrency,
    }),
    () => benchmarkRunner({
      metadata: {
        model_id: runtimeModel,
        adapter_id: checkedArtifact.finetune_id,
        source_sha: sourceSha,
        trigger: 'lora-gate-candidate',
        suite_digest: suiteDigest,
      },
      provenance: {
        artifact_digest: checkedArtifact.digest,
        training_manifest_digest: checkedArtifact.training_manifest_digest,
        dataset_digest: checkedArtifact.dataset_digest,
        approval_id: checkedApproval.approval_id,
      },
      respond: benchmarkResponder(ai, runtimeModel, extractText, { lora: checkedArtifact.finetune_id }),
      concurrency: benchmarkConcurrency,
    }),
  ], benchmarkSerial);
  baseline.passed = Array.isArray(baseline.cases) && baseline.cases.length > 0 && baseline.cases.every((row) => !row?.error);

  candidate.passed = Array.isArray(candidate.cases) && candidate.cases.length > 0 && candidate.cases.every((row) => !row?.error);

  const [impactBaseline, impactCandidate] = await runLoraBenchmarkPair([
    () => impactRunner({
      respond: benchmarkResponder(ai, runtimeModel, extractText),
      concurrency: benchmarkConcurrency,
    }),
    () => impactRunner({
      respond: benchmarkResponder(ai, runtimeModel, extractText, { lora: checkedArtifact.finetune_id }),
      concurrency: benchmarkConcurrency,
    }),
  ], benchmarkSerial);
  const impact = compareLoraImpact(impactBaseline, impactCandidate);

  const engine = createEngine(env);
  await engine.recordBenchmark({
    cases: baseline.cases,
    kind: 'lora-baseline',
    model_id: runtimeModel,
    source_sha: sourceSha,
    metadata: {
      suite_digest: suiteDigest,
      benchmark_id: baseline.benchmark_id,
      measured_score: baseline.overall,
      passed: baseline.passed,
    },
  });
  await engine.recordBenchmark({
    cases: candidate.cases,
    kind: 'lora-candidate',
    model_id: runtimeModel,
    adapter_id: checkedArtifact.finetune_id,
    source_sha: sourceSha,
    metadata: {
      suite_digest: suiteDigest,
      benchmark_id: candidate.benchmark_id,
      measured_score: candidate.overall,
      passed: candidate.passed,
      artifact_digest: checkedArtifact.digest,
      training_manifest_digest: checkedArtifact.training_manifest_digest,
      dataset_digest: checkedArtifact.dataset_digest,
      approval_id: checkedApproval.approval_id,
    },
  });
  const decision = await engine.evaluateAdapter({
    plan,
    artifact: checkedArtifact,
    approval: checkedApproval,
    baseline,
    candidate,
  });
  const impactGatePassed = impact.uncensored_gate === true;
  const stageReady = decision.promote === true && impactGatePassed;
  const nextStage = stageReady ? 'AGENTIC_READY' : 'UNCENSORED_CONTINUE';
  const activationBlocker = stageReady
    ? null
    : (decision.promote === true ? 'LORA_IMPACT_GATE_NOT_PASSED' : String(decision.reason || 'CANONICAL_BENCHMARK_NOT_PASSED'));

  await engine.recordBenchmark({
    cases: impactBaseline.cases,
    kind: 'lora-impact-baseline',
    model_id: runtimeModel,
    source_sha: sourceSha,
    metadata: {
      suite: impactBaseline.suite,
      version: impactBaseline.version,
      impact_metrics: impactBaseline.metrics,
      case_count: impactBaseline.case_count,
    },
  });
  await engine.recordBenchmark({
    cases: impactCandidate.cases,
    kind: 'lora-impact-candidate',
    model_id: runtimeModel,
    adapter_id: checkedArtifact.finetune_id,
    source_sha: sourceSha,
    metadata: {
      suite: impactCandidate.suite,
      version: impactCandidate.version,
      impact_metrics: impactCandidate.metrics,
      impact_delta: impact.delta,
      uncensored_gate: impactGatePassed,
      canonical_gate_passed: decision.promote === true,
      next_stage: nextStage,
      activation_blocker: activationBlocker,
      artifact_digest: checkedArtifact.digest,
      training_manifest_digest: checkedArtifact.training_manifest_digest,
      dataset_digest: checkedArtifact.dataset_digest,
      approval_id: checkedApproval.approval_id,
    },
  });

  let active = null;
  if (options.activate === true && stageReady) {
    active = await engine.activateAdapter({
      plan,
      artifact: checkedArtifact,
      approval: checkedApproval,
      baseline,
      candidate,
    });
  }

  return {
    plan_id: plan?.id || null,
    artifact: checkedArtifact,
    approval: checkedApproval,
    baseline,
    candidate,
    decision,
    impact: {
      baseline: impactBaseline,
      candidate: impactCandidate,
      comparison: impact,
    },
    next_stage: nextStage,
    impact_gate_passed: impactGatePassed,
    canonical_gate_passed: decision.promote === true,
    activation_blocker: activationBlocker,
    active,
    activated: Boolean(active),
    benchmark_concurrency: benchmarkConcurrency,
    benchmark_serial: benchmarkSerial,
    source_sha: sourceSha,
  };
}

export async function prepareOperatorLora(env = {}, options = {}, deps = {}) {
  const createEngine = deps.createLearningEngine || createLearningEngine;
  const engine = createEngine(env);
  const baseModel = cleanModelId(options.base_model || env.MEL_LORA_BASE_MODEL, undefined);
  const minQuality = cleanQuality(options.min_quality, 0.65);
  const prepared = await engine.prepareLora({
    ...(baseModel ? { base_model: baseModel } : {}),
    minQuality,
  });

  return {
    ...prepared,
    trainer: {
      available: false,
      status: 'NOT_CONFIGURED',
      reason: 'Aucun exécuteur d’entraînement LoRA externe n’est configuré dans ce Worker.',
    },
  };
}

// MEL-CHAT-06: one record per benchmark case (input, version, tools executed,
// result, metrics) with its source. Only real model answers are scored;
// fixtures and unavailable providers are counted apart, never averaged in.
const BENCHMARK_SOURCES = new Set(['MODEL', 'FIXTURE', 'UNAVAILABLE']);
export function benchmarkCaseRecord({ caseId, input, version, source, tools = [], result = null, metrics = {} } = {}) {
  const kind = String(source || '').toUpperCase();
  if (!BENCHMARK_SOURCES.has(kind)) throw Object.assign(new Error('BENCHMARK_CASE_SOURCE_INVALID'), { code: 'BENCHMARK_CASE_SOURCE_INVALID' });
  if (!caseId || !version) throw Object.assign(new Error('BENCHMARK_CASE_IDENTITY_REQUIRED'), { code: 'BENCHMARK_CASE_IDENTITY_REQUIRED' });
  const score = Number(metrics?.score);
  return Object.freeze({ case_id: String(caseId), input: String(input ?? '').slice(0, 4000), version: String(version), source: kind,
    tools: Object.freeze((Array.isArray(tools) ? tools : []).map(String).slice(0, 20)),
    result: kind === 'UNAVAILABLE' ? null : (result == null ? null : String(result).slice(0, 4000)),
    metrics: Object.freeze({ ...metrics, score: kind === 'MODEL' && Number.isFinite(score) ? score : null }) });
}
export function aggregateBenchmarkScore(records = []) {
  const scored = records.filter(row => row?.source === 'MODEL' && Number.isFinite(row?.metrics?.score));
  return Object.freeze({ overall: scored.length ? scored.reduce((sum, row) => sum + row.metrics.score, 0) / scored.length : null,
    scored_cases: scored.length,
    fixture_cases: records.filter(row => row?.source === 'FIXTURE').length,
    unavailable_cases: records.filter(row => row?.source === 'UNAVAILABLE').length });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  DEFAULT_OPERATOR_BENCHMARK_MODEL,
  ensureZeroCostBenchmarkBaseline,
  prepareOperatorLora,
  runOperatorBenchmark,
} from '../src/learning/operator-actions.js';

test('operator benchmark fails closed when Workers AI is unavailable', async () => {
  await assert.rejects(
    () => runOperatorBenchmark({}, {}, {}),
    (error) => error?.code === 'AI_BINDING_UNAVAILABLE' && error?.message === 'ai_binding_unavailable',
  );
});

test('operator benchmark executes model cases and persists measured evidence', async () => {
  const aiCalls = [];
  const recorded = [];
  const engine = {
    async recordBenchmark(value) {
      recorded.push(value);
      return { id: 'benchmark-memory-1', ...value };
    },
  };

  const result = await runOperatorBenchmark(
    {
      AI: {
        async run(model, request) {
          aiCalls.push({ model, request });
          return { response: '42' };
        },
      },
      MEL_SOURCE_SHA: 'source-sha-123',
    },
    {},
    {
      createLearningEngine: () => engine,
      runLearningBenchmark: async ({ respond, modelId, sourceSha, metadata }) => {
        const output = await respond('Réponds 42.');
        return {
          benchmark_id: `test:${sourceSha}:${modelId}`,
          version: 'test-v1',
          model_id: modelId,
          source_sha: sourceSha,
          metadata,
          case_count: 1,
          score: 1,
          cases: [{ id: 'case-1', domain: 'reasoning', output, weight: 1, score: 1 }],
        };
      },
    },
  );

  assert.equal(result.model_id, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(result.source_sha, 'source-sha-123');
  assert.equal(result.benchmark.score, 1);
  assert.equal(result.benchmark.metadata.source_sha, 'source-sha-123');
  assert.equal(result.benchmark.metadata.model_id, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(aiCalls.length, 1);
  assert.equal(aiCalls[0].model, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(aiCalls[0].request.temperature, 0);
  assert.equal(recorded.length, 1);
  assert.equal(recorded[0].kind, 'operator');
  assert.equal(recorded[0].model_id, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(recorded[0].source_sha, 'source-sha-123');
  assert.equal(recorded[0].metadata.trigger, 'professor');
  assert.equal(recorded[0].metadata.measured_score, 1);
});

test('operator benchmark honors only a configured model that is explicitly zero-cost', async () => {
  const models = [];
  const engine = { async recordBenchmark(value) { return value; } };
  const configuredModel = '@cf/meta/llama-3.3-70b-instruct-fp8-fast';
  const result = await runOperatorBenchmark(
    {
      AI: { async run(model) { models.push(model); return { response: 'ok' }; } },
      MEL_BENCHMARK_MODEL: configuredModel,
    },
    { model_id: '@cf/ignored/request-selected-model' },
    {
      createLearningEngine: () => engine,
      runLearningBenchmark: async ({ respond, modelId, sourceSha }) => ({
        benchmark_id: 'configured', version: 'test', model_id: modelId, source_sha: sourceSha,
        case_count: 1, score: 1,
        cases: [{ id: 'case', score: 1, weight: 1, output: await respond('ok') }],
      }),
    },
  );

  assert.equal(result.model_id, configuredModel);
  assert.deepEqual(models, [configuredModel]);
});

test('operator benchmark rejects an unknown or non-verified-cost configured model before calling AI', async () => {
  let called = false;
  await assert.rejects(
    () => runOperatorBenchmark({
      AI: { async run() { called = true; return { response: 'should-not-run' }; } },
      MEL_BENCHMARK_MODEL: '@cf/example/unknown-cost-model',
    }),
    (error) => error?.code === 'BENCHMARK_MODEL_NOT_VERIFIED_ZERO_COST',
  );
  assert.equal(called, false);
});

test('LoRA preparation persists a plan and explicitly reports that no trainer is configured', async () => {
  const inputs = [];
  const engine = {
    async prepareLora(input) {
      inputs.push(input);
      return {
        plan: { id: 'lora-plan-1', status: 'READY', examples: 25 },
        corpus: { accepted: 25, rejected: 2, digest: 'digest-1' },
      };
    },
  };

  const result = await prepareOperatorLora(
    { MEL_LORA_BASE_MODEL: '@cf/example/lora-base' },
    { min_quality: 0.72 },
    { createLearningEngine: () => engine },
  );

  assert.deepEqual(inputs, [{ base_model: '@cf/example/lora-base', minQuality: 0.72 }]);
  assert.equal(result.plan.status, 'READY');
  assert.equal(result.trainer.available, false);
  assert.equal(result.trainer.status, 'NOT_CONFIGURED');
  assert.match(result.trainer.reason, /Aucun exécuteur/);
});

test('LoRA quality input is clamped before reaching the learning engine', async () => {
  let received;
  const engine = {
    async prepareLora(input) {
      received = input;
      return { plan: { status: 'BLOCKED_DATA' }, corpus: {} };
    },
  };

  await prepareOperatorLora({}, { min_quality: 9 }, { createLearningEngine: () => engine });
  assert.equal(received.minQuality, 1);
});


test('baseline bootstrap runs the canonical suite once when the current suite has no baseline', async () => {
  let received = null;
  const engine = {
    async benchmarks() { return []; },
    async runCanonicalBenchmark(value) {
      received = value;
      return {
        reused: false,
        score: { overall: 0.75, cases: 7 },
        suite_digest: 'suite-current',
      };
    },
  };
  const result = await ensureZeroCostBenchmarkBaseline(
    {
      AI: { async run() { return { response: 'unused-by-stub-engine' }; } },
      MEL_SOURCE_SHA: 'bootstrap-source-sha',
    },
    { trigger: 'test-bootstrap' },
    { createLearningEngine: () => engine },
  );
  assert.equal(result.status, 'RAN');
  assert.equal(result.created, true);
  assert.equal(result.score, 0.75);
  assert.equal(result.cases, 7);
  assert.equal(result.model_id, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(result.source_sha, 'bootstrap-source-sha');
  assert.equal(received.kind, 'baseline');
  assert.equal(received.model_id, DEFAULT_OPERATOR_BENCHMARK_MODEL);
  assert.equal(received.source_sha, 'bootstrap-source-sha');
  assert.equal(received.metadata.trigger, 'test-bootstrap');
  assert.equal(typeof received.evaluator, 'function');
});

test('baseline bootstrap reuses a persisted baseline for the current canonical suite without calling AI', async () => {
  const { CANONICAL_LEARNING_BENCHMARK_SUITE, benchmarkSuiteFingerprint } = await import('../src/evaluation/benchmarks.js');
  const suiteDigest = benchmarkSuiteFingerprint(CANONICAL_LEARNING_BENCHMARK_SUITE);
  let aiCalled = false;
  let runCalled = false;
